head.script:
scwin.trigger1_onclick = function(e) {
    trigger1.setDisabled(true);
    //trigger1.setDisabled( false );
};
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.setVal = function() {
    scwin.fireOver(WebSquare.wUnit.getDomById($p.id + 'trigger1'));
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 버튼에 마우스를 오버한다.
    //1. Run the sample file and mouse over the button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "3000");
    //Verify 1. 툴팁내용이 보여진다.
    //1. Tooltip contents are displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_0_balloonTip').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 버튼을 클릭한다.
    //2. Click the button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 버튼이 비활성화(disabled)되고 툴팁이 보이지 않는다.(이전에는 툴팁이 계속 남아서 보여짐)
    //2. The button is disabled and the tooltip is not visible (previously the tooltip remains visible)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_0_balloonTip').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
